/** Best-effort push to one user's devices (never breaks the admin action). */
function pushToUser(int $userId, string $title, string $body, array $data = []): void
{
    try {
        $stmt = db()->prepare('SELECT token FROM kukupaja_device_tokens WHERE user_id = ?');
        $stmt->execute([$userId]);
        fcm_send_to_tokens($stmt->fetchAll(PDO::FETCH_COLUMN), $title, $body, $data, db());
    } catch (Throwable $e) { /* ignore */ }
}

function e(mixed $value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function redirect(string $query = ''): never { header('Location: index.php' . $query); exit; }
function statusLabel(string $status): string { return ['pending'=>'Imepokelewa','confirmed'=>'Imethibitishwa','assigned'=>'Imetumwa kwa broker','accepted'=>'Broker amekubali','preparing'=>'Inaandaliwa','in_transit'=>'Inasafirishwa','delivered'=>'Imewasilishwa','completed'=>'Imekamilika','cancelled'=>'Imefutwa','refunded'=>'Fedha imerejeshwa','paid'=>'Imelipwa','failed'=>'Imeshindikana'][$status] ?? $status; }
function createPayoutsForOrder(PDO $pdo, int $orderId): int {
    $order=$pdo->prepare("SELECT status,payment_status FROM kukupaja_orders WHERE id=?");
    $order->execute([$orderId]); $order=$order->fetch();
    if(!$order || $order['status']!=='completed' || $order['payment_status']!=='paid') return 0;
    $amounts=$pdo->prepare("SELECT p.broker_id,SUM(p.supplier_price*oi.quantity) supplier_amount FROM kukupaja_order_items oi JOIN kukupaja_products p ON p.id=oi.product_id WHERE oi.order_id=? GROUP BY p.broker_id");
    $amounts->execute([$orderId]); $created=0;
    foreach($amounts->fetchAll() as $amount) {
        $exists=$pdo->prepare('SELECT id FROM kukupaja_payouts WHERE order_id=? AND broker_id=? LIMIT 1');
        $exists->execute([$orderId,$amount['broker_id']]);
        if($exists->fetchColumn()) continue;
        $pdo->prepare("INSERT INTO kukupaja_payouts(broker_id,order_id,supplier_amount,status) VALUES(?,?,?,'pending')")
            ->execute([(int)$amount['broker_id'],$orderId,(float)$amount['supplier_amount']]);
        $created++;
    }
    return $created;
}
function nextOrderStatuses(string $status): array {
    return [
        'pending'=>['confirmed','cancelled'],
        'confirmed'=>['preparing','cancelled'],
        'assigned'=>['cancelled'],
        'accepted'=>['preparing','cancelled'],
        'preparing'=>['in_transit','cancelled'],
        'in_transit'=>['delivered','cancelled'],
        'delivered'=>['completed'],
    ][$status] ?? [];
}

