    if ($action === 'approve') {
        $productId=(int)($_POST['product_id']??0); $customerPrice=(float)($_POST['customer_price']??0);
        $product=db()->prepare('SELECT broker_id,name,supplier_price FROM kukupaja_products WHERE id=?'); $product->execute([$productId]);
        $productRow=$product->fetch();
        if(!$productRow) throw new RuntimeException('Bidhaa haijapatikana.');
        if($customerPrice<(float)$productRow['supplier_price']) throw new RuntimeException('Bei ya mteja haiwezi kuwa chini ya bei ya broker.');
        db()->prepare("UPDATE kukupaja_products SET customer_price=?,status='approved',rejection_reason=NULL,approved_by=?,approved_at=NOW() WHERE id=?")
            ->execute([$customerPrice, $_SESSION['admin_id'], $productId]);
