        $_SESSION['flash'] = 'Bidhaa imeidhinishwa.';
    } elseif ($action === 'reject') {
        $reason=trim((string)($_POST['reason']??''));
        if($reason==='') throw new RuntimeException('Weka sababu ya kukataa bidhaa.');
        $productId=(int)($_POST['product_id']??0);
        $rejRow=db()->prepare('SELECT broker_id,name FROM kukupaja_products WHERE id=?'); $rejRow->execute([$productId]); $rejRow=$rejRow->fetch();
        db()->prepare("UPDATE kukupaja_products SET status='rejected',rejection_reason=? WHERE id=?")
            ->execute([$reason, $productId]);
        if($rejRow) pushToUser((int)$rejRow['broker_id'],'Bidhaa haijaidhinishwa ❌','"'.(string)$rejRow['name'].'" imekataliwa. Sababu: '.$reason,['type'=>'product_rejected','product_id'=>(string)$productId]);
        $_SESSION['flash'] = 'Bidhaa imekataliwa.';
    } elseif ($action === 'expire_product') {
        db()->prepare("UPDATE kukupaja_products SET status='expired' WHERE id=? AND status='approved'")
            ->execute([(int)$_POST['product_id']]);
        $_SESSION['flash'] = 'Listing imeondolewa sokoni.';
    } elseif ($action === 'toggle_broker_verified') {
        db()->prepare("UPDATE kukupaja_users SET is_verified=IF(is_verified=1,0,1) WHERE id=? AND role='broker'")
            ->execute([(int)$_POST['broker_id']]);
        $_SESSION['flash'] = 'Uthibitisho wa broker umebadilishwa.';
    } elseif ($action === 'assign') {
        $pdo=db(); $pdo->beginTransaction();
        $item=$pdo->prepare("SELECT oi.order_id,oi.product_id,oi.quantity,p.broker_id,o.status FROM kukupaja_order_items oi JOIN kukupaja_products p ON p.id=oi.product_id JOIN kukupaja_orders o ON o.id=oi.order_id WHERE oi.id=? FOR UPDATE");
        $item->execute([(int)$_POST['order_item_id']]); $item=$item->fetch();
        if(!$item) throw new RuntimeException('Bidhaa ya oda haijapatikana.');
        if(!in_array($item['status'],['confirmed','assigned'],true)) throw new RuntimeException('Thibitisha oda kabla ya kuituma kwa broker.');
        $exists=$pdo->prepare("SELECT id FROM kukupaja_order_assignments WHERE order_id=? AND product_id=? AND status IN ('pending','accepted','fulfilled')");
        $exists->execute([$item['order_id'],$item['product_id']]);
        if($exists->fetch()) throw new RuntimeException('Bidhaa hii tayari imetumwa kwa broker.');
        $pdo->prepare("INSERT INTO kukupaja_order_assignments(order_id,broker_id,product_id,quantity,status,deadline) VALUES(?,?,?,?,'pending',?)")
            ->execute([$item['order_id'],$item['broker_id'],$item['product_id'],$item['quantity'],$_POST['deadline']]);
        $pdo->prepare("UPDATE kukupaja_orders SET status='assigned' WHERE id=?")->execute([$item['order_id']]);
        $pdo->commit(); $_SESSION['flash']='Oda imetumwa kwa broker.';
    } elseif ($action === 'status') {
        $next=(string)($_POST['status']??''); $orderId=(int)$_POST['order_id'];
        if($next!=='') {
            $pdo=db(); $pdo->beginTransaction();
            $stmt=$pdo->prepare('SELECT status FROM kukupaja_orders WHERE id=? FOR UPDATE'); $stmt->execute([$orderId]); $old=(string)$stmt->fetchColumn();
            if($old==='') throw new RuntimeException('Oda haijapatikana.');
            if(in_array($old,['completed','cancelled','refunded'],true)) throw new RuntimeException('Oda iliyofungwa haiwezi kubadilishwa.');
            if(!in_array($next,nextOrderStatuses($old),true)) throw new RuntimeException('Hatua hii hairuhusiwi kutoka '.statusLabel($old).'.');
            $items=$pdo->prepare('SELECT oi.product_id,oi.quantity,p.available_stock FROM kukupaja_order_items oi JOIN kukupaja_products p ON p.id=oi.product_id WHERE oi.order_id=? FOR UPDATE');
            $items->execute([$orderId]); $items=$items->fetchAll();
            if($next==='confirmed' && $old==='pending') foreach($items as $item) {
                if((int)$item['available_stock'] < (int)$item['quantity']) throw new RuntimeException('Stock haitoshi kwa bidhaa moja ya oda.');
                $pdo->prepare('UPDATE kukupaja_products SET available_stock=available_stock-?,reserved_stock=reserved_stock+? WHERE id=?')->execute([$item['quantity'],$item['quantity'],$item['product_id']]);
            }
            if($next==='cancelled' && in_array($old,['confirmed','assigned','accepted','preparing','in_transit','delivered'],true)) foreach($items as $item) {
                $pdo->prepare('UPDATE kukupaja_products SET available_stock=available_stock+?,reserved_stock=GREATEST(reserved_stock-?,0) WHERE id=?')->execute([$item['quantity'],$item['quantity'],$item['product_id']]);
            }
            if($next==='completed') foreach($items as $item) {
                $pdo->prepare('UPDATE kukupaja_products SET reserved_stock=GREATEST(reserved_stock-?,0),sold_stock=sold_stock+? WHERE id=?')->execute([$item['quantity'],$item['quantity'],$item['product_id']]);
            }
            $pdo->prepare('UPDATE kukupaja_orders SET status=?,updated_at=NOW() WHERE id=?')->execute([$next,$orderId]);
            $createdPayouts=createPayoutsForOrder($pdo,$orderId);
            $pdo->commit();
            if($createdPayouts>0) $_SESSION['flash']=$createdPayouts.' payout zimeandaliwa.';
        }
        if(empty($_SESSION['flash'])) $_SESSION['flash']='Hali ya oda imebadilishwa.';
    } elseif ($action === 'payment_status') {
        $orderId=(int)($_POST['order_id']??0); $paymentStatus=(string)($_POST['payment_status']??'');
        if(!in_array($paymentStatus,['pending','paid','refunded'],true)) throw new RuntimeException('Hali ya malipo si sahihi.');
        $pdo=db(); $pdo->beginTransaction();
        $stmt=$pdo->prepare('SELECT id FROM kukupaja_orders WHERE id=? FOR UPDATE'); $stmt->execute([$orderId]);
        if(!$stmt->fetchColumn()) throw new RuntimeException('Oda haijapatikana.');
        $pdo->prepare('UPDATE kukupaja_orders SET payment_status=?,updated_at=NOW() WHERE id=?')->execute([$paymentStatus,$orderId]);
        $createdPayouts=createPayoutsForOrder($pdo,$orderId);
        $pdo->commit();
        $_SESSION['flash']=$createdPayouts>0 ? 'Malipo yamethibitishwa na payout imeandaliwa.' : 'Hali ya malipo imebadilishwa.';
    } elseif ($action === 'generate_payout') {
        $pdo=db(); $pdo->beginTransaction();
        $created=createPayoutsForOrder($pdo,(int)($_POST['order_id']??0));
        $pdo->commit();
        $_SESSION['flash']=$created>0 ? $created.' payout zimeandaliwa.' : 'Hakuna payout mpya ya kuandaa kwa oda hii.';
    } elseif ($action === 'payout_status') {
        $payoutId=(int)($_POST['payout_id']??0); $payoutStatus=(string)($_POST['payout_status']??'');
        $reference=trim((string)($_POST['reference']??''));
        if(!in_array($payoutStatus,['pending','paid','failed'],true)) throw new RuntimeException('Hali ya payout si sahihi.');
        if($payoutStatus==='paid' && $reference==='') throw new RuntimeException('Weka reference ya malipo.');
        $stmt=db()->prepare("UPDATE kukupaja_payouts SET status=?,reference=?,paid_at=IF(?='paid',NOW(),NULL) WHERE id=?");
        $stmt->execute([$payoutStatus,$reference,$payoutStatus,$payoutId]);
        if($stmt->rowCount()<1) throw new RuntimeException('Payout haijapatikana au haijabadilika.');
        $_SESSION['flash']='Payout imesasishwa.';
    } elseif ($action === 'create_ad') {
        db()->prepare('INSERT INTO kukupaja_advertisements(advertiser_name,title,subtitle,image_url,button_text,target_category,amount_paid,starts_at,ends_at,is_active,created_by) VALUES(?,?,?,?,?,?,?,?,?,1,?)')
            ->execute([trim((string)$_POST['advertiser_name']),trim((string)$_POST['title']),trim((string)$_POST['subtitle']),trim((string)$_POST['image_url']),trim((string)$_POST['button_text']),$_POST['target_category'],(float)$_POST['amount_paid'],$_POST['starts_at'],$_POST['ends_at'],$_SESSION['admin_id']]);
