        db()->prepare('UPDATE kukupaja_advertisements SET is_active=IF(is_active=1,0,1) WHERE id=?')->execute([(int)$_POST['ad_id']]);
        $_SESSION['flash']='Hali ya tangazo imebadilishwa.';
    } elseif ($action === 'send_message') {
        $receiverId=(int)($_POST['chat_user']??0);
        $message=trim((string)($_POST['message']??''));
        if($message==='') throw new RuntimeException('Andika ujumbe kwanza.');
        if(mb_strlen($message)>2000) throw new RuntimeException('Ujumbe ni mrefu sana.');
        $receiver=db()->prepare("SELECT id FROM kukupaja_users WHERE id=? AND role IN ('customer','broker') AND is_active=1");
        $receiver->execute([$receiverId]);
        if(!$receiver->fetchColumn()) throw new RuntimeException('Mpokeaji hajapatikana.');
        db()->prepare('INSERT INTO kukupaja_messages(sender_id,receiver_id,message) VALUES(?,?,?)')
            ->execute([$_SESSION['admin_id'],$receiverId,$message]);
        $_SESSION['flash']='Ujumbe umetumwa.';
    }
    } catch (Throwable $exception) {
        if (isset($pdo) && $pdo instanceof PDO && $pdo->inTransaction()) $pdo->rollBack();
        $_SESSION['error_flash'] = $exception->getMessage();
    }
    $returnPage=(string)($_POST['return_page']??'dashboard');
    $returnQuery='?page='.urlencode($returnPage);
    if($returnPage==='messages' && isset($_POST['chat_user'])) $returnQuery.='&chat_user='.(int)$_POST['chat_user'];
    redirect($returnQuery);
}

