        $chatStmt=db()->prepare('SELECT m.*,s.name sender_name FROM kukupaja_messages m JOIN kukupaja_users s ON s.id=m.sender_id WHERE (m.sender_id=? AND m.receiver_id=?) OR (m.sender_id=? AND m.receiver_id=?) ORDER BY m.id ASC LIMIT 300');
        $chatStmt->execute([$adminId,$selectedChatId,$selectedChatId,$adminId]); $chatMessages=$chatStmt->fetchAll();
    }
}
$flash=$_SESSION['flash']??''; unset($_SESSION['flash']);
$errorFlash=$_SESSION['error_flash']??''; unset($_SESSION['error_flash']);
