<?php elseif($page==='ads'):?><h1>Matangazo ya Kulipia</h1><details class="app-action-sheet"><summary>Chapisha Tangazo Jipya</summary><div class="sheet-content"><form method="post" class="assign"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="create_ad"><input type="hidden" name="return_page" value="ads"><label>Muuzaji<input name="advertiser_name" required></label><label>Kichwa<input name="title" required></label><label>Maelezo<input name="subtitle"></label><label>Image URL<input name="image_url"></label><label>Button<input name="button_text" value="Angalia Sasa"></label><label>Category<select name="target_category"><option value="wote">Wote</option><option value="kienyeji">Kienyeji</option><option value="broiler">Broiler</option><option value="kuku_wakisasa">Kuku wa Kisasa</option><option value="mayai">Mayai</option><option value="vifaranga">Vifaranga</option><option value="vingine">Vingine</option></select></label><label>Kiasi Kilicholipwa<input type="number" name="amount_paid" min="0" value="0"></label><label>Kuanzia<input type="datetime-local" name="starts_at" required></label><label>Mpaka<input type="datetime-local" name="ends_at" required></label><button>Chapisha Tangazo</button></form></div></details><div class="panel scroll"><table class="mobile-card-table"><tr><th>Muuzaji</th><th>Tangazo</th><th>Category</th><th>Malipo</th><th>Muda</th><th>Hali</th></tr><?php foreach($ads as $ad):?><tr><td data-label="Muuzaji"><?=e($ad['advertiser_name'])?></td><td data-label="Tangazo"><b><?=e($ad['title'])?></b><div class="muted"><?=e($ad['subtitle'])?></div></td><td data-label="Category"><?=e($ad['target_category'])?></td><td data-label="Malipo">TSh <?=number_format((float)$ad['amount_paid'])?></td><td data-label="Muda"><?=e($ad['starts_at'])?><br><?=e($ad['ends_at'])?></td><td data-label="Hali"><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="toggle_ad"><input type="hidden" name="return_page" value="ads"><input type="hidden" name="ad_id" value="<?=e($ad['id'])?>"><button class="<?=$ad['is_active']?'':'red'?>"><?=$ad['is_active']?'Active':'Inactive'?></button></form></td></tr><?php endforeach?></table></div>
