<?php else:?><h1>Malipo na Payouts</h1><p class="muted">Payout hutengenezwa baada ya oda kukamilika na malipo ya mteja kuthibitishwa.</p><div class="finance-grid"><div class="finance-card"><small>Inasubiri kulipwa</small><b>TSh <?=number_format($payoutStats['pending'])?></b></div><div class="finance-card"><small>Imelipwa</small><b>TSh <?=number_format($payoutStats['paid'])?></b></div><div class="finance-card"><small>Malipo yaliyoshindikana</small><b>TSh <?=number_format($payoutStats['failed'])?></b></div></div><?php if($eligiblePayoutOrders):?><details class="app-action-sheet"><summary>Andaa Payout Mpya</summary><div class="sheet-content"><form method="post" class="assign"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="generate_payout"><input type="hidden" name="return_page" value="payouts"><label>Oda iliyolipwa na kukamilika<select name="order_id" required><option value="">Chagua oda...</option><?php foreach($eligiblePayoutOrders as $eligible):?><option value="<?=e($eligible['id'])?>"><?=e($eligible['order_number'])?></option><?php endforeach?></select></label><button>Hesabu na andaa payout</button></form></div></details><?php endif?><div class="panel"><?php if(!$payouts):?><div class="empty-state"><div class="empty-icon">▣</div><h2>Hakuna payout bado</h2><p>Kamisha oda na thibitisha malipo ya mteja; payout ya kila broker itaandaliwa moja kwa moja.</p></div><?php else:?><div class="section-head"><h2>Historia ya payouts</h2><span class="muted"><?=count($payouts)?> rekodi</span></div><div class="scroll"><table class="mobile-card-table"><tr><th>Oda</th><th>Broker</th><th>Kiasi</th><th>Hali ya sasa</th><th>Sasisha payout</th><th>Tarehe</th></tr><?php foreach($payouts as $payout):?><tr><td data-label="Oda"><?=e($payout['order_number'])?></td><td data-label="Broker"><?=e($payout['broker_name'])?></td><td data-label="Kiasi"><b>TSh <?=number_format((float)$payout['supplier_amount'])?></b></td><td data-label="Hali"><span class="tag <?=e($payout['status'])?>"><?=e(statusLabel($payout['status']))?></span><div class="muted"><?=e($payout['reference']?:'Hakuna reference')?></div></td><td data-label="Sasisha payout"><form method="post" class="payout-action"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="payout_status"><input type="hidden" name="return_page" value="payouts"><input type="hidden" name="payout_id" value="<?=e($payout['id'])?>"><select name="payout_status" required><option value="pending" <?=$payout['status']==='pending'?'selected':''?>>Inasubiri</option><option value="paid" <?=$payout['status']==='paid'?'selected':''?>>Imelipwa</option><option value="failed" <?=$payout['status']==='failed'?'selected':''?>>Imeshindikana</option></select><input name="reference" value="<?=e($payout['reference'])?>" placeholder="Transaction reference"><button>Hifadhi</button></form></td><td data-label="Tarehe"><?=e($payout['paid_at']?:$payout['created_at'])?></td></tr><?php endforeach?></table></div><?php endif?></div><?php endif?></main></div><script>function toggleSidebar(){document.body.classList.toggle('sidebar-collapsed');localStorage.setItem('kukupaja-sidebar',document.body.classList.contains('sidebar-collapsed')?'closed':'open')}function toggleMobileNav(force){const open=typeof force==='boolean'?force:!document.body.classList.contains('mobile-nav-open');document.body.classList.toggle('mobile-nav-open',open);const button=document.querySelector('.mobile-menu-toggle');if(button)button.setAttribute('aria-expanded',open?'true':'false')}document.addEventListener('keydown',event=>{if(event.key==='Escape')toggleMobileNav(false)});if(localStorage.getItem('kukupaja-sidebar')==='closed'&&innerWidth>700)document.body.classList.add('sidebar-collapsed');const stream=document.getElementById('messageStream');if(stream)stream.scrollTop=stream.scrollHeight;</script></body></html>
